def gkeys(x):
 g,a,m,h=x
 return ((),(a,),(g,a),(a,h),(g,a,h))
def priors(D):
 counts=collections.defaultdict(lambda:[0]*5)
 for x in D:
  for g in gkeys(x): counts[g][labels[x]+2]+=1
 def pi(x):
