 return {x:pi(x) for x in keys}
def episodes(m,a):
 xs=[x for x in keys if x[2]==m and x[1]==a]
 fold={g:i%5 for i,g in enumerate(sorted({x[0] for x in xs}))}
 return [([x for x in xs if fold[x[0]]==f],[x for x in xs if fold[x[0]]"'!=f]) for f in range(5)]
def replay(T,Q,pi,theta,mode,forced=None):
 k,wg,wh=theta
 C=[0]*5; G=collections.defaultdict(lambda:[0]*5); H=collections.defaultdict(lambda:[0]*5)
 tr=[]; avail=list(Q); nt=collections.Counter(t[3] for t in T)
 def p(x):
  nc=[C[i]+wg*G[x[0]][i]+wh*H[x[3]][i] for i in range(5)]
  d=k+sum(nc)
  return tuple((k*pi[x][i]+nc[i])/d for i in range(5))
 def W(x): return F(len(T)+wh*nt[x[3]])
 def U(x): return 1-sum(v*v for v in p(x))
 def V(x): return sum((F(n*(1+wh*(h==x[3])),k+len(tr)+wh*sum(H[h])) for h,n in nt.items()),F(0))
 order=None
 if forced is not None: order=forced
 elif mode=='"'\\''K0'\\'': order=Q
 elif mode=='\\''K1'\\'': order=Q[::-1]
 elif mode in ('\\''K2'\\'','\\''K3'\\'','\\''K4'\\'','\\''K5'\\''):
  score={'\\''K2'\\'':lambda x:-U(x),'\\''K3'\\'':U,'\\''K4'\\'':lambda x:-W(x),'\\''K5'\\'':lambda x:-U(x)*W(x)}[mode]
  order=sorted(Q,key=lambda x:(score(x),x))
 for step in range(20):
  if order is not None: q=order[step]
  else:
   sf={'\\''U'\\'':U,'\\''W'\\'':W,'\\''V'\\'':V,'\\''UW'\\'':lambda x:U(x)*W(x),'\\''UV'\\'':lambda x:U(x)*V(x)}[mode]
   # avail stays canonical ascending; max keeps first exact tie.
